"use client"

import * as React from "react"

import { Slot } from "@radix-ui/react-slot"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"
import { Dialog, DialogActions, DialogClose, DialogSurface, DialogTrigger, useDialog } from "@/components/ui/dialog"

/** What opened the sheet, so a fold can grow out of it. */
const Opener = React.createContext<React.RefObject<HTMLElement | null> | null>(null)

/** A page slid in from the edge. Same props and behaviour as Dialog: the native <dialog> keeps focus, Escape and the top layer. */
function Sheet(props: React.ComponentProps<typeof Dialog>) {
  const openerRef = React.useRef<HTMLElement | null>(null)
  return (
    <Opener.Provider value={openerRef}>
      <Dialog {...props} />
    </Opener.Provider>
  )
}

/** Opens the sheet. It remembers itself, so a fold sheet grows from it (a Row, through `<Row asChild><SheetTrigger>`). */
function SheetTrigger({ onClick, ...props }: React.ComponentProps<typeof DialogTrigger>) {
  const openerRef = React.useContext(Opener)
  return (
    <DialogTrigger
      {...props}
      onClick={(e) => {
        if (openerRef) openerRef.current = e.currentTarget
        onClick?.(e)
      }}
    />
  )
}

const SheetClose = DialogClose

type SheetContentProps = React.ComponentProps<"dialog"> & {
  /** Which edge it slides from. Logical, so start is the right edge in right-to-left. */
  side?: "start" | "end" | "top" | "bottom"
  /**
   * spine: the title runs up the spine, in its own column. shelf: a sheet opened from inside it stands in
   * front, one spine narrower, so this one's spine stays in view like a book on a shelf, and is the way back.
   * rag: the text is set flush to the window's edge, and the paper is cut to the rag of its lines.
   * fold: the row that opened it unfolds into the page: its two hairlines part to the window's edges and its
   * name grows into the page's title. Put it away and the page folds back into the row.
   */
  variant?: "spine" | "shelf" | "rag" | "fold"
}

type Rag = { w: number; h: number; fill: string; line: string }

/**
 * Cuts the paper to the words: every line box in the sheet, merged into rows, stepped out by the padding on
 * the side that faces the page. Measured from the live layout (the fonts, the pair and the width decide the
 * rag), so it re-cuts on resize and when <html> changes its face.
 */
function useRag(probe: React.RefObject<HTMLElement | null>, on: boolean) {
  const { open } = useDialog()
  const [rag, setRag] = React.useState<Rag | null>(null)

  React.useEffect(() => {
    const d = probe.current?.closest("dialog")
    if (!on || !open || !d) return
    let frame = 0
    const cut = () => {
      const box = d.getBoundingClientRect()
      const style = getComputedStyle(d)
      const pad = parseFloat(style.paddingInlineEnd) || 40
      // Which physical edge it stands on: end is the right in left-to-right, start is the right in right-to-left.
      const right = (d.dataset.side !== "start") !== (style.direction === "rtl")
      const rows: { top: number; bottom: number; x: number }[] = []
      const walk = document.createTreeWalker(d, NodeFilter.SHOW_TEXT, {
        acceptNode: (n) => (n.parentElement?.closest("svg, .ot-scrollbar, .ot-sr") || !n.textContent?.trim() ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT),
      })
      const range = document.createRange()
      for (let n = walk.nextNode(); n; n = walk.nextNode()) {
        range.selectNodeContents(n)
        for (const r of range.getClientRects()) {
          if (r.width < 1) continue
          rows.push({ top: r.top - box.top + d.scrollTop, bottom: r.bottom - box.top + d.scrollTop, x: (right ? r.left : r.right) - box.left })
        }
      }
      if (!rows.length) return
      rows.sort((a, b) => a.top - b.top)
      const merged = [rows[0]]
      for (const r of rows.slice(1)) {
        const last = merged[merged.length - 1]
        // Same line when its middle falls inside the last: tight leading makes the next line's box overlap this one.
        if ((r.top + r.bottom) / 2 < last.bottom) Object.assign(last, { bottom: Math.max(last.bottom, r.bottom), x: right ? Math.min(last.x, r.x) : Math.max(last.x, r.x) })
        else merged.push({ ...r })
      }
      const w = d.clientWidth
      const h = d.scrollHeight
      const at = (x: number) => Math.round(Math.min(w, Math.max(0, right ? x - pad : x + pad)))
      const edge = right ? w : 0
      let line = `M${at(merged[0].x)} 0`
      merged.forEach((r, i) => {
        const next = merged[i + 1]
        const y = next ? Math.round((r.bottom + next.top) / 2) : h - 1
        line += ` V${y}`
        if (next) line += ` H${at(next.x)}`
      })
      line += ` H${edge}`
      setRag({ w, h, line, fill: `M${edge} 0 H${at(merged[0].x)}${line.slice(line.indexOf(" "))} Z` })
      d.setAttribute("data-laid", "")
    }
    const soon = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(cut)
    }
    document.fonts.ready.then(soon)
    const resized = new ResizeObserver(soon)
    resized.observe(d)
    const restyled = new MutationObserver(soon)
    restyled.observe(document.documentElement, { attributes: true })
    return () => {
      cancelAnimationFrame(frame)
      resized.disconnect()
      restyled.disconnect()
    }
  }, [probe, on, open])

  return rag
}

const ms = (v: string) => (v.trim().endsWith("ms") ? parseFloat(v) : parseFloat(v) * 1000) || 0

/**
 * Fold: the page grows out of what opened it. Before the dialog opens (and again before it closes) the opener's
 * box is written to --fold-t/r/b/l, so the clip and the two hairlines open out from the row and fold back to it
 * in CSS. The title flies between the row's name and its own place by a transform, measured both ways.
 */
function useFold(probe: React.RefObject<HTMLElement | null>, on: boolean) {
  const { open } = useDialog()
  const openerRef = React.useContext(Opener)
  const flip = React.useCallback((d: HTMLElement, from: HTMLElement | null, title: HTMLElement | null) => {
    if (!from || !title) return null
    const a = from.getBoundingClientRect()
    const b = title.getBoundingClientRect()
    const fa = getComputedStyle(from)
    const fb = getComputedStyle(title)
    const s = parseFloat(fa.fontSize) / parseFloat(fb.fontSize)
    const lh = (st: CSSStyleDeclaration) => parseFloat(st.lineHeight) || parseFloat(st.fontSize) * 1.2
    const rtl = fb.direction === "rtl"
    title.style.transformOrigin = rtl ? "100% 0" : "0 0"
    // The first lines' middles meet, whatever each one's leading.
    const dx = rtl ? a.right - b.right : a.left - b.left
    const dy = a.top + lh(fa) / 2 - (b.top + (lh(fb) * s) / 2)
    const style = getComputedStyle(d)
    return {
      transform: `translate(${dx}px, ${dy}px) scale(${s})`,
      duration: ms(style.getPropertyValue("--ot-andante")),
      easing: style.getPropertyValue("--ot-exhale").trim() || "ease-out",
    }
  }, [])

  // Before showModal and before close: where the row is now, and whether it stands reversed out of ink.
  React.useLayoutEffect(() => {
    const d = probe.current?.closest("dialog")
    if (!on || !d) return
    const from = openerRef?.current ?? null
    const r = from?.isConnected ? from.getBoundingClientRect() : null
    const px = (v: number) => `${Math.round(Math.max(0, v))}px`
    for (const [k, v] of Object.entries(r ? { t: r.top, r: innerWidth - r.right, b: innerHeight - r.bottom, l: r.left } : {})) d.style.setProperty(`--fold-${k}`, px(v))
    d.toggleAttribute("data-from-ink", !!from?.matches('.ot-rows:not([data-variant]) .ot-rows-link:is(:hover, :focus-visible)'))
    // Closing (the page still laid out, before close() or while Escape's close plays): the title flies back.
    const title = d.querySelector<HTMLElement>(".ot-sheet-title")
    if (open || !title?.getClientRects().length) return
    const f = flip(d, from?.querySelector<HTMLElement>("[data-slot=rows-title]") ?? from, title)
    if (f && title && !matchMedia("(prefers-reduced-motion: reduce)").matches) title.animate([{ transform: "none" }, { transform: f.transform }], { duration: f.duration, easing: f.easing, fill: "forwards" })
  }, [probe, on, open, openerRef, flip])

  // Opened: the row's name grows into the title.
  React.useEffect(() => {
    const d = probe.current?.closest("dialog")
    const title = d?.querySelector<HTMLElement>(".ot-sheet-title") ?? null
    if (!on || !open || !d || !title) return
    title.getAnimations().forEach((a) => a.cancel())
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) return
    const from = openerRef?.current ?? null
    const f = flip(d, from?.isConnected ? (from.querySelector<HTMLElement>("[data-slot=rows-title]") ?? from) : null, title)
    if (f) title.animate([{ transform: f.transform }, { transform: "none" }], { duration: f.duration, easing: f.easing })
  }, [probe, on, open, openerRef, flip])
}

function SheetContent({ className, side = "end", variant = "spine", children, onClick, ...props }: SheetContentProps) {
  const { setOpen } = useDialog()
  const probe = React.useRef<HTMLSpanElement>(null) // DialogSurface keeps the dialog's own ref; the rag and the fold find it from here
  const ragged = variant === "rag" && (side === "start" || side === "end")
  const rag = useRag(probe, ragged)
  useFold(probe, variant === "fold")
  return (
    <DialogSurface
      data-slot="sheet-content"
      data-side={side}
      data-variant={variant === "spine" ? undefined : variant}
      className={cn("ot-sheet", className)}
      onClick={(e) => {
        onClick?.(e)
        // A rag sheet's box is wider than its paper: a click on the bare part is a click outside.
        if (ragged && e.target === e.currentTarget) setOpen(false)
      }}
      {...props}
    >
      {children}
      {ragged && rag && (
        <svg className="ot-sheet-rag" aria-hidden="true" width={rag.w} height={rag.h} viewBox={`0 0 ${rag.w} ${rag.h}`}>
          <path className="ot-sheet-rag-paper" d={rag.fill} />
          <path className="ot-sheet-rag-edge" d={rag.line} pathLength={1} />
        </svg>
      )}
      {(ragged || variant === "fold") && <span ref={probe} hidden />}
    </DialogSurface>
  )
}

type PanelsContextValue = { path: string[]; root: string; go: (to: string, from: HTMLElement | null) => void }
const PanelsContext = React.createContext<PanelsContextValue | null>(null)

function usePanels() {
  const ctx = React.useContext(PanelsContext)
  if (!ctx) throw new Error("SheetPanel and SheetPanelLink must sit inside <SheetPanels>.")
  return ctx
}

type SheetPanelsProps = Omit<React.ComponentProps<"div">, "defaultValue"> & {
  /** The panel it opens on, the root of the trail. Each opening of the sheet starts here again. */
  defaultValue: string
  /** Called with the panel you arrive at. */
  onValueChange?: (value: string) => void
}

/**
 * Pages inside one sheet, the chapters of the book on its spine. Stepping into a panel writes its name up the
 * spine, large, and the name you left shrinks into the pencil below it; the names below are the way back. The
 * panels must be direct children: their titles are read from them to set the trail.
 */
function SheetPanels({ defaultValue, onValueChange, className, children, ref: forwardedRef, ...props }: SheetPanelsProps) {
  const { open } = useDialog()
  const [path, setPath] = React.useState([defaultValue])
  const [step, setStep] = React.useState<"in" | "out">("in")
  const openers = React.useRef<(HTMLElement | null)[]>([])
  const host = React.useRef<HTMLDivElement>(null)
  const composedRef = useComposedRefs(host, forwardedRef)
  const titles = new Map<string, React.ReactNode>()
  React.Children.forEach(children, (c) => {
    if (React.isValidElement<SheetPanelProps>(c) && c.props.value) titles.set(c.props.value, c.props.title)
  })

  // Put away, it opens on the root next time.
  if (!open && path.length > 1) setPath([defaultValue])

  const arrive = (next: string[], dir: "in" | "out", focus: () => HTMLElement | null | undefined) => {
    setStep(dir)
    setPath(next)
    onValueChange?.(next[next.length - 1])
    requestAnimationFrame(() => {
      host.current?.closest("dialog")?.scrollTo({ top: 0 })
      focus()?.focus({ preventScroll: true })
    })
  }
  const heading = () => host.current?.querySelector<HTMLElement>(".ot-sheet-panel:not([hidden]) > .ot-sheet-panel-title")
  const go = (to: string, from: HTMLElement | null) => {
    if (to === path[path.length - 1] || !titles.has(to)) return
    openers.current[path.length - 1] = from
    arrive([...path, to], "in", heading)
  }
  const back = (depth: number) => arrive(path.slice(0, depth + 1), "out", () => openers.current[depth] ?? heading())

  return (
    <PanelsContext.Provider value={{ path, root: defaultValue, go }}>
      <div ref={composedRef} data-slot="sheet-panels" data-step={step} className={cn("ot-sheet-panels", className)} {...props}>
        {/* The spine is the trail: the root at the foot, the panel you are in written large at the head. */}
        <nav className="ot-sheet-spine ot-sheet-trail" aria-label="Path">
          {path.map((v, i) => {
            const here = i === path.length - 1
            return (
              <button
                key={v}
                type="button"
                className="ot-sheet-trail-step"
                aria-current={here ? "page" : undefined}
                aria-disabled={here || undefined}
                onClick={() => !here && back(i)}
              >
                {titles.get(v)}
              </button>
            )
          })}
        </nav>
        {children}
      </div>
    </PanelsContext.Provider>
  )
}

type SheetPanelProps = Omit<React.ComponentProps<"section">, "title"> & {
  value: string
  /** Its name: the panel's heading, and its step on the spine. */
  title: React.ReactNode
}

/** One page of the sheet. Only the one you are in is shown; the others wait, hidden and inert. */
function SheetPanel({ value, title, className, children, ...props }: SheetPanelProps) {
  const { path, root } = usePanels()
  const { titleId } = useDialog()
  const here = path[path.length - 1] === value
  return (
    <section data-slot="sheet-panel" hidden={!here} inert={!here} aria-label={typeof title === "string" ? title : undefined} className={cn("ot-sheet-panel", className)} {...props}>
      <h2 id={value === root ? titleId : undefined} tabIndex={-1} className="ot-sheet-title ot-sheet-panel-title">
        {title}
      </h2>
      {children}
    </section>
  )
}

type SheetPanelLinkProps = React.ComponentProps<"button"> & { to: string; asChild?: boolean }

/** Steps into another panel. Bare, it is a line of type with the arrow that says it opens; asChild lends the move to your own control. */
function SheetPanelLink({ to, asChild = false, className, children, onClick, ...props }: SheetPanelLinkProps) {
  const { go } = usePanels()
  const Comp = asChild ? Slot : "button"
  return (
    <Comp
      data-slot="sheet-panel-link"
      className={asChild ? className : cn("ot-sheet-panel-link", className)}
      onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(e)
        if (!e.defaultPrevented) go(to, e.currentTarget)
      }}
      {...(asChild ? {} : { type: "button" as const })}
      {...props}
    >
      {asChild ? children : (
        <>
          <span>{children}</span>
          <span aria-hidden="true" className="ot-sheet-panel-arrow">→</span>
        </>
      )}
    </Comp>
  )
}

/** The sheet's name, running up its spine like a book's. Decorative: the visible title is SheetTitle. */
function SheetSpine({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="sheet-spine" aria-hidden="true" className={cn("ot-sheet-spine", className)} {...props} />
}

function SheetTitle({ className, ...props }: React.ComponentProps<"h2">) {
  const { titleId } = useDialog()
  return <h2 data-slot="sheet-title" id={titleId} className={cn("ot-sheet-title", className)} {...props} />
}

function SheetDescription({ className, ...props }: React.ComponentProps<"p">) {
  const { descriptionId } = useDialog()
  return <p data-slot="sheet-description" id={descriptionId} className={cn("ot-sheet-body", className)} {...props} />
}

function SheetActions(props: React.ComponentProps<"div">) {
  return <DialogActions data-slot="sheet-actions" {...props} />
}

export {
  Sheet, SheetTrigger, SheetContent, SheetSpine, SheetTitle, SheetDescription, SheetActions, SheetActions as SheetFooter, SheetClose,
  SheetPanels, SheetPanel, SheetPanelLink,
  type SheetContentProps, type SheetPanelsProps, type SheetPanelProps, type SheetPanelLinkProps,
}

@layer components {
  /* ── ot-sheet ── a page slid in from the edge; its title runs up the spine.
     The backdrop lives in dialog.css. Sides are logical: start and end follow
     the reading direction, so the sheet meets the right edge in right-to-left. */
  .ot-sheet {
    --from: 100% 0; /* where it waits, off the edge it comes from */
    position: fixed; inset-block: 0; inset-inline: auto 0; margin: 0; width: min(32rem, calc(100vw - var(--ot-space-6))); height: 100dvh; max-width: none; max-height: none;
    padding-block: var(--ot-space-7) var(--ot-space-6); padding-inline: var(--ot-space-8) var(--ot-space-6); overflow: auto;
    border: 0; border-inline-start: var(--ot-hairline) solid var(--ot-ink); background: var(--ot-paper); color: var(--ot-graphite);
    translate: var(--from);
    transition: translate var(--ot-andante) var(--ot-exhale), overlay var(--ot-andante) allow-discrete, display var(--ot-andante) allow-discrete;
  }
  .ot-sheet[open] { translate: 0 0; }
  @starting-style { .ot-sheet[open] { translate: var(--from); } }
  .ot-sheet:is([dir="rtl"], [dir="rtl"] *) { --from: -100% 0; }
  .ot-sheet[data-side="start"] { --from: -100% 0; inset-inline: 0 auto; border-inline-start: 0; border-inline-end: var(--ot-hairline) solid var(--ot-ink); }
  .ot-sheet[data-side="start"]:is([dir="rtl"], [dir="rtl"] *) { --from: 100% 0; }
  /* A start sheet's edge is on the same side as its scrollbar: the edge is the rail, and the thumb is that edge thickening where you are, not a second line beside it. */
  .ot-sheet[data-side="start"] > .ot-scrollbar { --line: 0px; }
  .ot-sheet[data-side="start"] > .ot-scrollbar::before { content: none; }
  .ot-sheet:is([data-side="top"], [data-side="bottom"]) { inset-inline: 0; width: 100%; height: auto; max-height: 85dvh; border-inline-start: 0; }
  .ot-sheet[data-side="top"] { --from: 0 -100%; inset-block: 0 auto; border-block-end: var(--ot-hairline) solid var(--ot-ink); }
  .ot-sheet[data-side="bottom"] { --from: 0 100%; inset-block: auto 0; border-block-start: var(--ot-hairline) solid var(--ot-ink); }
  /* left and right, not inset-inline-start: in the spine's own vertical writing mode that means top,
     and the spine fell into the text. The sheet's space-8 inline-start padding is its column. */
  .ot-sheet-spine {
    position: absolute; left: var(--ot-space-4); bottom: var(--ot-space-6);
    writing-mode: vertical-rl; rotate: 180deg; white-space: nowrap;
    font-size: var(--ot-f); line-height: 1; letter-spacing: var(--ot-f-tr); font-weight: 200; color: var(--ot-ink);
  }
  .ot-sheet-spine:is([dir="rtl"], [dir="rtl"] *) { left: auto; right: var(--ot-space-4); }
  .ot-sheet[open] .ot-sheet-spine { animation: ot-spine var(--ot-andante) var(--ot-exhale) 240ms backwards; }
  @keyframes ot-spine { from { clip-path: inset(0 0 100% 0); } to { clip-path: inset(0); } }
  .ot-sheet > * + *:not(.ot-scrollbar) { margin-block-start: var(--ot-space-6); }
  .ot-sheet-title { font-size: var(--ot-mf); line-height: var(--ot-mf-lh); letter-spacing: var(--ot-mf-tr); font-weight: 300; color: var(--ot-ink); }
  .ot-sheet-body { max-width: 40ch; }

  /* Shelf (books on a shelf): a sheet opened from inside a shelf sheet stands in front of it, one spine column
     narrower, so the spine below stays in view, set back to pencil, and pointing there puts the front one away.
     Only the front sheet blurs the page; the ones behind it are the shelf. */
  .ot-sheet[data-variant="shelf"] { --col: var(--ot-space-8); --wide: min(32rem, calc(100vw - var(--ot-space-6))); }
  .ot-sheet[data-variant="shelf"] .ot-sheet { width: calc(var(--wide) - var(--col)); }
  .ot-sheet[data-variant="shelf"] .ot-sheet .ot-sheet { width: calc(var(--wide) - 2 * var(--col)); }
  .ot-sheet[data-variant="shelf"] .ot-sheet::backdrop { background: none; -webkit-backdrop-filter: none; backdrop-filter: none; }
  .ot-sheet[data-variant="shelf"] .ot-sheet-spine { transition: color var(--ot-moderato) var(--ot-breath); }
  .ot-sheet[data-variant="shelf"]:has(.ot-sheet[open]) > .ot-sheet-spine,
  .ot-sheet[data-variant="shelf"] .ot-sheet:has(.ot-sheet[open]) > .ot-sheet-spine { color: var(--ot-pencil); }
  @media (max-width: 40rem) {
    .ot-sheet[data-variant="shelf"] { --col: var(--ot-space-7); }
    .ot-sheet[data-variant="shelf"], .ot-sheet[data-variant="shelf"] .ot-sheet { padding-inline-start: var(--col); }
    .ot-sheet[data-variant="shelf"] .ot-sheet-spine { left: var(--ot-space-3); font-size: var(--ot-mf); }
    .ot-sheet[data-variant="shelf"] .ot-sheet-spine:is([dir="rtl"], [dir="rtl"] *) { left: auto; right: var(--ot-space-3); }
  }

  /* Rag ("Healthy habits" cut from its paper; "Less is more." set flush right): the words stand flush to the
     window's edge and rag toward the page, and the paper is cut to that rag, a step for every line, with a
     hairline along the cut that draws down as it arrives. The script measures the line boxes and draws the
     paper (.ot-sheet-rag); until it has, the sheet is plain paper. Its box hangs from the top, only as tall
     as its words, and a click on the bare part of the box is a click outside. */
  .ot-sheet[data-variant="rag"] { height: auto; max-height: 100dvh; inset-block: 0 auto; isolation: isolate; padding-inline: var(--ot-space-6); text-align: end; }
  .ot-sheet[data-variant="rag"][data-laid] { background: none; border: 0; }
  .ot-sheet[data-variant="rag"] > :not(.ot-scrollbar, .ot-sheet-rag) { margin-inline-start: auto; }
  .ot-sheet[data-variant="rag"] .ot-sheet-title { font-size: var(--ot-f); line-height: var(--ot-f-lh); letter-spacing: var(--ot-f-tr); text-wrap: balance; }
  .ot-sheet[data-variant="rag"] .ot-sheet-body { max-width: 30ch; }
  .ot-sheet[data-variant="rag"][data-laid] > .ot-scrollbar { --line: 0px; }
  .ot-sheet[data-variant="rag"][data-laid] > .ot-scrollbar::before { content: none; }
  .ot-sheet > .ot-sheet-rag { position: absolute; z-index: -1; top: 0; margin: 0; left: 0; overflow: visible; pointer-events: none; }
  .ot-sheet-rag-paper { fill: var(--ot-paper); pointer-events: visiblePainted; }
  .ot-sheet-rag-edge { fill: none; stroke: var(--ot-ink); stroke-width: var(--ot-hairline); stroke-dasharray: 1; shape-rendering: crispEdges; }
  .ot-sheet[open] .ot-sheet-rag-edge { animation: ot-rag var(--ot-andante) var(--ot-exhale) 200ms backwards; }
  @keyframes ot-rag { from { stroke-dashoffset: 1; } }
  /* Panels: pages inside one sheet, the chapters of the book on its spine ("It has to be design.": the scale is the
     drama). The spine is the trail, read up from the foot: the names you came through small in the pencil, the one
     you are in large in ink. Stepping in, the name you left shrinks into the trail and the new one writes up the
     spine; the page slides in from the edge the sheet came from while the old one goes the other way. The small
     names are the way back. Panels share one cell, so the two pages cross in place. */
  .ot-sheet-panels { --lr: 1; display: grid; }
  .ot-sheet-panels:is([dir="rtl"], [dir="rtl"] *) { --lr: -1; }
  .ot-sheet-panels[data-step="out"] { --lr-step: -1; }
  .ot-sheet-panel {
    grid-area: 1 / 1; min-inline-size: 0;
    transition: opacity var(--ot-andante) var(--ot-exhale), translate var(--ot-andante) var(--ot-exhale), display var(--ot-andante) allow-discrete;
  }
  .ot-sheet-panel[hidden] { opacity: 0; translate: calc(-1.5em * var(--lr) * var(--lr-step, 1)) 0; pointer-events: none; }
  @starting-style { .ot-sheet-panel:not([hidden]) { opacity: 0; translate: calc(1.5em * var(--lr) * var(--lr-step, 1)) 0; } }
  .ot-sheet-panel > * + * { margin-block-start: var(--ot-space-6); }
  .ot-sheet-panel-title { inline-size: fit-content; }
  .ot-sheet-panel-title:focus { outline: none; }
  .ot-sheet-panel-title:focus-visible { outline: var(--ot-stroke) solid var(--ot-accent); outline-offset: 6px; }

  .ot-sheet-trail { display: flex; align-items: baseline; gap: var(--ot-space-4); }
  .ot-sheet-trail:is([dir="rtl"], [dir="rtl"] *) { flex-direction: row-reverse; } /* the root stays at the foot */
  .ot-sheet-trail-step {
    appearance: none; border: 0; padding: 0; background: none; font: inherit; letter-spacing: 0; cursor: pointer;
    font-size: var(--ot-mp); font-weight: 400; color: var(--ot-pencil);
    transition: font-size var(--ot-andante) var(--ot-exhale), font-weight var(--ot-andante) var(--ot-exhale), color var(--ot-allegro);
  }
  .ot-sheet-trail-step:hover { color: var(--ot-ink); }
  .ot-sheet-trail-step[aria-current] { font-size: var(--ot-f); font-weight: 200; letter-spacing: var(--ot-f-tr); color: var(--ot-ink); cursor: default; }
  .ot-sheet-trail-step[aria-current]:last-child:not(:first-child) { animation: ot-spine var(--ot-andante) var(--ot-exhale) backwards; }
  .ot-sheet-trail-step:focus-visible { outline: var(--ot-stroke) solid var(--ot-accent); outline-offset: 4px; }

  .ot-sheet-panel-link {
    appearance: none; display: flex; justify-content: space-between; align-items: baseline; gap: var(--ot-space-4); inline-size: 100%;
    border: 0; border-block-end: var(--ot-hairline) solid var(--ot-rule); background: none; padding: var(--ot-space-3) 0; text-align: start; cursor: pointer;
    font: inherit; font-size: var(--ot-mp); line-height: var(--ot-mp-lh); letter-spacing: var(--ot-mp-tr); color: var(--ot-ink);
  }
  .ot-sheet-panel-link + .ot-sheet-panel-link { margin-block-start: 0; }
  .ot-sheet-panel-arrow { color: var(--ot-pencil); transition: translate var(--ot-allegro) var(--ot-exhale), color var(--ot-allegro); }
  .ot-sheet-panel-arrow:is([dir="rtl"], [dir="rtl"] *) { scale: -1 1; }
  .ot-sheet-panel-link:is(:hover, :focus-visible, [data-force~="hover"]) .ot-sheet-panel-arrow { color: var(--ot-ink); translate: calc(0.25em * var(--lr)) 0; }
  @media (max-width: 40rem) {
    .ot-sheet-trail-step[aria-current] { font-size: var(--ot-mf); letter-spacing: var(--ot-mf-tr); }
    .ot-sheet-trail-step { font-size: var(--ot-p); }
  }
  @media (forced-colors: active) {
    .ot-sheet-rag-paper { fill: Canvas; }
    .ot-sheet-rag-edge { stroke: CanvasText; }
  }

  /* Fold (the index entry that opens to its page; "Less is more." set between hairlines): the row that opened it
     unfolds into the page. The script writes the row's box to --fold-t/r/b/l before it opens and before it closes;
     the clip opens from that band to the window, the row's two hairlines part with its edges to the top and the
     foot, and the row's name grows into the title (a transform, in the script). The rest arrives once there is
     room for it. Put away, it all folds back into the row. With no opener, a line at the middle parts. */
  .ot-sheet[data-variant="fold"] {
    --fold: inset(var(--fold-t, 50%) var(--fold-r, 0px) var(--fold-b, 50%) var(--fold-l, 0px));
    inset: 0; width: 100%; max-width: none; height: 100dvh; border: 0; translate: none; overscroll-behavior: contain;
    padding-block: var(--ot-space-8) var(--ot-space-7); padding-inline: var(--ot-margin);
    clip-path: var(--fold);
    transition: clip-path var(--ot-andante) var(--ot-exhale), background-color var(--ot-allegro) var(--ot-breath), overlay var(--ot-andante) allow-discrete, display var(--ot-andante) allow-discrete;
  }
  .ot-sheet[data-variant="fold"][open] { translate: none; clip-path: inset(0); }
  @starting-style {
    .ot-sheet[data-variant="fold"][open] { translate: none; clip-path: var(--fold); }
    .ot-sheet[data-variant="fold"][data-from-ink][open] { background-color: var(--ot-ink); }
  }
  /* The row's hairlines, riding the clip's edges. Fixed, so they hold to the window while the page scrolls. */
  .ot-sheet[data-variant="fold"]::before, .ot-sheet[data-variant="fold"]::after {
    content: ""; position: fixed; z-index: 4; left: var(--fold-l, 0px); right: var(--fold-r, 0px); height: var(--ot-hairline); background: var(--ot-ink); pointer-events: none;
    transition: top var(--ot-andante) var(--ot-exhale), bottom var(--ot-andante) var(--ot-exhale), left var(--ot-andante) var(--ot-exhale), right var(--ot-andante) var(--ot-exhale);
  }
  .ot-sheet[data-variant="fold"]::before { top: var(--fold-t, 50%); }
  .ot-sheet[data-variant="fold"]::after { bottom: var(--fold-b, 50%); }
  .ot-sheet[data-variant="fold"][open]::before { top: 0; left: 0; right: 0; }
  .ot-sheet[data-variant="fold"][open]::after { bottom: 0; left: 0; right: 0; }
  @starting-style {
    .ot-sheet[data-variant="fold"][open]::before { top: var(--fold-t, 50%); left: var(--fold-l, 0px); right: var(--fold-r, 0px); }
    .ot-sheet[data-variant="fold"][open]::after { bottom: var(--fold-b, 50%); left: var(--fold-l, 0px); right: var(--fold-r, 0px); }
  }
  .ot-sheet[data-variant="fold"] .ot-sheet-spine { display: none; }
  .ot-sheet[data-variant="fold"] .ot-sheet-title { max-inline-size: 14ch; font-size: var(--ot-ff); line-height: var(--ot-ff-lh); letter-spacing: var(--ot-ff-tr); font-weight: 300; text-wrap: balance; transition: color var(--ot-allegro) var(--ot-breath); }
  @starting-style { .ot-sheet[data-variant="fold"][data-from-ink][open] .ot-sheet-title { color: var(--ot-paper); } }
  .ot-sheet[data-variant="fold"] > :not(.ot-sheet-title, .ot-scrollbar) { opacity: 0; transition: opacity var(--ot-allegro) var(--ot-breath); }
  .ot-sheet[data-variant="fold"][open] > :not(.ot-sheet-title, .ot-scrollbar) { opacity: 1; transition: opacity var(--ot-moderato) var(--ot-exhale) calc(var(--ot-andante) / 2); }
  @starting-style { .ot-sheet[data-variant="fold"][open] > :not(.ot-sheet-title, .ot-scrollbar) { opacity: 0; } }
  .ot-sheet[data-variant="fold"] .ot-sheet-body { max-inline-size: var(--ot-measure); font-size: var(--ot-mp); line-height: var(--ot-mp-lh); letter-spacing: var(--ot-mp-tr); }
  .ot-sheet[data-variant="fold"] .ot-dialog-actions { justify-content: flex-start; }
  @media (max-width: 40rem) {
    .ot-sheet[data-variant="fold"] { padding-block: var(--ot-space-7) var(--ot-space-6); }
    .ot-sheet[data-variant="fold"] .ot-sheet-title { font-size: var(--ot-f); line-height: var(--ot-f-lh); letter-spacing: var(--ot-f-tr); }
    .ot-sheet[data-variant="fold"] .ot-sheet-body { font-size: var(--ot-p); line-height: var(--ot-p-lh); }
  }
  @media (forced-colors: active) {
    .ot-sheet[data-variant="fold"]::before, .ot-sheet[data-variant="fold"]::after { forced-color-adjust: none; background: CanvasText; }
  }
}
